override WORKGROUP_SIZE: u32 = 32u;
struct Params { length: u32, output_offset: u32, first: f32, second: f32 }
@group(0) @binding(0) var<storage, read> left_values: array<f32>;
@group(0) @binding(1) var<storage, read> right_values: array<f32>;
@group(0) @binding(2) var<storage, read_write> output_values: array<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@compute @workgroup_size(WORKGROUP_SIZE, 1, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let i = gid.x;
  if (i >= params.length) { return; }
  let x = left_values[i];
  let y = right_values[i];
  var value: f32 = 0.0;
for (var i = 0u; i < params.length; i += 1u) {
  var next = left_values[(i + 1u) % params.length];
  var prev = left_values[(i - 2u + params.length) % params.length];
  value = prev - 2.0 * next;
}
  output_values[params.output_offset + i] = value;
}

